create or replace TABLE LDL_DATA_PRODUCTION.CORE_APP_FRAUD_DETECTION.T_STATISTICS_BY_STORE_HOUR_CASHIER_2 cluster by (BUS_DT)(
	INT_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the internal organization.',
	BUS_DT DATE NOT NULL COMMENT 'The business date to which the measures are related.',
	CASHIER_NR VARCHAR(20) NOT NULL COMMENT 'The number which identifies the cashier. (The number is unique for a given store and a day.)',
	EVENT_END_HR NUMBER(38,0) NOT NULL COMMENT 'Holds the hour from \""Event end tmsp\"", so for example if the receipt close at \""13:34:56\"", the value in the column will be \""13\"".',
	SALES_NET_VAL NUMBER(38,5) COMMENT 'The net amount which was generated by sales_2 in that store on the given day according to the cash register.',
	RETURN_NET_VAL NUMBER(38,5) COMMENT 'The total value of return transactions performed in that store on the given day by one cashier',
	EVENT_CNT NUMBER(38,0) COMMENT 'The number of transactions (logoffs, returns, sales_2 etc.) performed in that store on the given day by one cashier',
	EVENT_LINE_CNT NUMBER(38,0) COMMENT 'The number of all transactions lines (returns, sales_2 etc.) performed in that store on the given day by one cashier',
	RETURN_CNT NUMBER(38,0) COMMENT 'The number of return transactions performed in that store on the given day by one cashier',
	CANCELLED_LINE_CNT NUMBER(38,0) COMMENT 'The number of cancelled transactions lines performed in that store on the given day by one cashier',
	CANCELLED_NET_VAL NUMBER(38,5) COMMENT 'The total value of cancelled transactions lines performed in that store on the given day by one cashier',
	DISCOUNT_LINE_CNT NUMBER(38,0) COMMENT 'The number of discount transactions lines performed in that store on the given day by one cashier',
	DISCOUNT_NET_VAL NUMBER(38,5) COMMENT 'The total value of discount transactions lines performed in that store on the given day by one cashier',
	ABORT_CNT NUMBER(38,0) COMMENT 'The number of abort transactions performed in that store on the given day by one cashier',
	ABORT_NET_VAL NUMBER(38,5) COMMENT 'The total value of abort transactions performed in that store on the given day by one cashier',
	SUSPENDED_UNRESOLVED_CNT NUMBER(38,0) COMMENT 'The number of the retail event was suspended and has never been resolved transactions, performed in that store on the given day by one cashier',
	SUSPENDED_UNRESOLVED_NET_VAL NUMBER(38,5) COMMENT 'The total of the retail event was suspended and has never been resolved transactions, performed in that store on the given day by one cashier',
	PRICE_INFO_CNT NUMBER(38,0) COMMENT 'The number of price info transactions performed in that store on the given day by one cashier',
	RETURN_WITHOUT_RECEIPT_CNT NUMBER(38,0) COMMENT 'The number of the retail event contained a return without the original receipt. I.e. there was no receipt number or the receipt number could not be foun in that store on the given day by one cashier',
	RETURN_WITHOUT_RECEIPT_NET_VAL NUMBER(38,5) COMMENT 'The total of the retail event contained a return without the original receipt. I.e. there was no receipt number or the receipt number could not be found in that store on the given day by one cashier',
	IS_OUTLIER_DAY_RETURN_FG BOOLEAN COMMENT 'Flag which marks the days with the highest two and lowest two return percentages (return value / turnover value), and it''s only relevant for the manual KPI \""Geldrückgabenquote\"".',
	DEPOSIT_SALES_NET_VAL NUMBER(38,5) COMMENT 'The total of the deposits which got sold over the cash register in that store on the given day by one cashier',
	DEPOSIT_RETURN_NET_VAL NUMBER(38,5) COMMENT 'The total of the deposits which got returned over the deposit maschine and payout over the cash register in that store on the given day by one cashier',
	DEPOSIT_RETURN_MANUAL_INPUT_NET_VAL NUMBER(38,5) COMMENT 'The total of the manual deposits which got returned over the deposit maschine and payout over the cash register in that store on the given day by one cashier',
	DEPOSIT_RETURN_MANUAL_INPUT_GROSS_VAL NUMBER(38,5) COMMENT 'The total gross of the manual deposits which got returned over the deposit maschine and payout over the cash register in that store on the given day by one cashier',
	DEPOSIT_ONLY_RETURN_NET_VAL NUMBER(38,5) COMMENT 'The total of the deposits in this case just the receipts which have just one or many deposit in (but just deposits), in that store on the given day by one cashier',
	SMALL_SALES_CNT NUMBER(38,0) COMMENT 'The number of the the retail event contained only one product and if the total value is less than a pre-defined threshold (e.g. 1€) in that store on the given day by one cashier',
	LOGIN_CNT NUMBER(38,0) COMMENT 'The number of the retail logins event in that store on the given day by one cashier',
	LOGOFF_CNT NUMBER(38,0) COMMENT 'The number of the logoffs in that store on the given day by one cashier',
	SALES_OUTSIDE_WORK_HR_NET_VAL NUMBER(38,5) COMMENT 'The total which was generated by sales_2 in that store outside work hours (before opening/after closing) on the given day according to the cash register.',
	RETURN_OUTSIDE_WORK_HR_NET_VAL NUMBER(38,5) COMMENT 'The total of return transactions performed in that store outside work hours (before opening/after closing) on the given day by one cashier.',
	SALES_OUTSIDE_WORK_HR_CNT NUMBER(38,0) COMMENT 'The number of sales_2 transactions performed in that store outside work hours (before opening/after closing) on the given day by one cashier.',
	RETURN_OUTSIDE_WORK_HR_CNT NUMBER(38,0) COMMENT 'The number of return transactions performed in that store outside work hours (before opening/after closing) on the given day by one cashier.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_STATISTICS_BY_STORE_HOUR_CASHIER primary key (BUS_DT, INT_ORG_SID, CASHIER_NR, EVENT_END_HR)
)COMMENT='An aggregate fact holding the grain store, day, cashier. Additional to that this table is used for the manuall KPIs, which have a general condition (example >200 receipt for certain fraud detection period or the cashier needs to work at least 7 days in this fraud detection period)'
;